    ('public', 'satisfaction_surveys', 'valid_professionalism_rating', 'ALTER TABLE "public"."satisfaction_surveys" ADD CONSTRAINT "valid_professionalism_rating" CHECK ("professionalism_rating" IS NULL OR ("professionalism_rating" >= 1 AND "professionalism_rating" <= 5)) NOT VALID'),
