    target := to_regclass(format('%I.%I', r.schema_name, r.table_name));
    IF target IS NULL THEN
      RAISE EXCEPTION 'platform declared checks fail-closed: %.% does not exist.', r.schema_name, r.table_name;
    END IF;
    SELECT contype INTO existing FROM pg_constraint WHERE conrelid = target AND conname = r.constraint_name;
    IF FOUND THEN
      IF existing <> 'c' THEN
        RAISE EXCEPTION 'platform declared checks fail-closed: %.% already has a constraint named % that is not a check.', r.schema_name, r.table_name, r.constraint_name;
      END IF;
      CONTINUE;
    END IF;
    EXECUTE r.ddl;
    BEGIN
      EXECUTE format('ALTER TABLE %I.%I VALIDATE CONSTRAINT %I', r.schema_name, r.table_name, r.constraint_name);
    EXCEPTION WHEN check_violation THEN
      RAISE EXCEPTION 'platform declared checks fail-closed: rows of %.% violate %; repair or remove them before this migration.', r.schema_name, r.table_name, r.constraint_name;
    END;
    EXECUTE format('COMMENT ON CONSTRAINT %I ON %I.%I IS %L', r.constraint_name, r.schema_name, r.table_name, 'platform-migration:declared_checks');
